MP="py -3.13 <your-picture-maker>/make-picture.py"
STY="Bold simple doodle drawn with one thick black whiteboard marker on a pure white background, like a friendly teacher's whiteboard sketch: every line exactly the same thickness, thick round-ended lines, lines well spaced apart, no double lines, no thin lines, no small details, no texture, no dots, no shading, no hatching, black and white only, no text, centred with a wide white margin, no frame."
NEG="colour, colored, coloured fill, brown, tan, orange, yellow, green, red, lettuce, leaves, tomato, cheese, shading, hatching, cross-hatching, stippling, dots, texture lines, double lines, thin lines, fine lines, varying line weight, grey tones, gradient, photo, realistic, 3d render, text, letters, words, numbers, watermark, logo, signature, blurry, low quality, sketchy messy lines, frame, border, paper edge"
O=assets_work/wb
$MP "$STY Subject: two slices of white sandwich bread standing side by side, front view, each slice the classic bread-slice shape with a domed rounded top, one crust line drawn just inside the outer edge of each slice." $O/bread_e --n 4 --seed 141 --negative "$NEG"
$MP "$STY Subject: an open jar of peanut butter with a plain blank label band, a butter knife dipped into the jar with its handle sticking out, the round lid lying flat beside the jar." $O/jar_e --n 4 --seed 241 --negative "$NEG"
$MP "$STY Subject: one slice of bread seen from slightly above, covered with a layer of peanut butter drawn as a wavy outline just inside the crust, a butter knife lying across it, three curved swoosh lines on the spread." $O/spread_e --n 4 --seed 341 --negative "$NEG"
$MP "$STY Subject: two triangle sandwich halves on a round plate, slightly apart, each half two bread layers with one smooth band of peanut butter between them showing on the cut edge." $O/halves_e --n 4 --seed 641 --negative "$NEG"
$MP "$STY Subject, top view from directly above: a rectangular cutting board, on it a square sandwich shaped like a bread slice with a domed top, a big chef's knife lying on top exactly along the diagonal from the top-left corner to the bottom-right corner." $O/cut_e --n 4 --seed 541 --negative "$NEG"
